@Test
public void testGenericMessage() throws Exception {
    GenericRecord record1 = new GenericData.Record(SCHEMA);
    record1.put("name", "Black Jack");
    record1.put("favorite_number", 11);
    record1.put("favorite_color", "Black");
    ByteBufferEncoder<GenericRecord> encoder = new AvroMessageEncoder<GenericRecord>();
    AvroMessageDecoder<User> decoder = new AvroMessageDecoder<User>(SCHEMA);
    User message = decoder.decode(IoBuffer.wrap(encoder.encode(record1)));
    assertEquals(record1.get("name"), message.getName());
    assertEquals(record1.get("favorite_number"), message.getFavoriteNumber());
    assertEquals(record1.get("favorite_color"), message.getFavoriteColor());
}

/**
 * Send "numberOfMessages" messages to a server. Currently, 1 million, with two different
 * size, 10Ko and 64Ko.
 */
@Test
public void benchmark() throws IOException, InterruptedException {
    CountDownLatch counter = new CountDownLatch(numberOfMessages);
    CounterFilter.messageSent.set(0);
    boolean result = true;
    System.out.println("-------------- Sending " + data.length + " bytes");
    client.start(port, counter, data);
    long globalSent = 0;
    long warmedUpSent = 0;
    int nbSeconds = 0;
    while ((counter.getCount() > 0) && (nbSeconds < 120)) {
        result = counter.await(1, TimeUnit.SECONDS);
        long nbSent = CounterFilter.messageSent.getAndSet(0);
        nbSeconds++;
        globalSent += nbSent;
        if (nbSeconds > 5) {
            warmedUpSent += nbSent;
        }
        System.out.print("Nb messages sent per second : " + nbSent + "\r");
    }
    System.out.println();
    if (nbSeconds < 120) {
        System.out.println("Average : " + (warmedUpSent / (nbSeconds - 5)) + ", for " + globalSent + " messages sent in " + nbSeconds + "s");
    } else {
        System.out.println("Wasn't able to send all the messages : sent " + globalSent);
    }
    assertTrue("Still " + counter.getCount() + " messages to send of a total of " + numberOfMessages, result);
}

