@Test
public void checkDecodingIn2Steps() {
    IntPartialDecoder decoder = new IntPartialDecoder();
    ByteBuffer buffer = ByteBuffer.wrap(new byte[] { 0x00, 0x00 });
    assertFalse(decoder.consume(buffer));
    buffer = ByteBuffer.wrap(new byte[] { 0x00, 0x00, 0x00 });
    assertTrue(decoder.consume(buffer));
    assertEquals(0, decoder.getValue().intValue());
    assertEquals(1, buffer.remaining());
}

@Test
public void testDynamic() throws Exception {
    ByteBufferEncoder<Person> encoder = getEncoder();
    ProtobufDynamicMessageDecoder decoder = new ProtobufDynamicMessageDecoder();
    for (Person object : getObjects()) {
        ProtobufSerializedMessage message = decoder.decode(IoBuffer.wrap(encoder.encode(object)));
        assertEquals(object, message.get(Person.class));
    }
}

@Test
public void testDynamic() throws Exception {
    ByteBufferEncoder<UserProfile> encoder = getEncoder();
    ThriftDynamicMessageDecoder decoder = new ThriftDynamicMessageDecoder();
    for (UserProfile object : getObjects()) {
        ThriftDynamicMessageDecoder.ThriftSerializedMessage message = decoder.decode(IoBuffer.wrap(encoder.encode(object)));
